files.content:
body {
  font-family: Georgia, serif;
  background: #fff5e6;
  color: #4a2c1a;
  margin: 0;
}

header {
  background: #f4a6b8;
  text-align: center;
  padding: 20px;
}

a {
  color: #4a2c1a;
  font-size: 18px;
}

section {
  background: white;
  margin: 20px;
  padding: 20px;
  border: 2px solid #f4a6b8;
  border-radius: 12px;
}

h2 {
  color: #c0506b;
}

footer {
  text-align: center;
  padding: 10px;
}

